(function(){
  'use strict';
  const root=document.getElementById('infra-observer'),content=root.querySelector('#io-content'),feedback=root.querySelector('#io-feedback');
  const C=window.InfraLogsCore,inv=window.InfraInventory,db=()=>inv.data(),esc=inv.helpers.esc;
  const initial=window.InfraLogsData.seed(db()),key='infrascope.logs.v1';
  const defaults={version:1,sources:initial.sources,views:[],rules:[
    {id:'lr-api',name:'office-api 错误突增',source:'ls-office',q:'level:ERROR',window:5,threshold:10,severity:'严重',receiver:'业务值班组',channel:'企业微信 + 邮件',enabled:true},
    {id:'lr-login',name:'Windows 连续登录失败',source:'ls-windows',q:'event:4625',window:5,threshold:8,severity:'警告',receiver:'IT 运维组',channel:'企业微信 + 邮件',enabled:true},
    {id:'lr-billing',name:'billing-worker 内存错误',source:'ls-billing',q:'pattern:worker_memory',window:5,threshold:1,severity:'严重',receiver:'财务系统值班组',channel:'企业微信',enabled:true}
  ],runtime:{},retention:{hot:14,archive:90,audit:180},actions:[]};
  let state=structuredClone(defaults),storageOK=true;
  try{const old=JSON.parse(localStorage.getItem(key));if(old?.version===1)state={...state,...old};}catch{storageOK=false;}
  let records=C.dedupe(initial.rows.map(r=>({...r,ingestedAt:r.observedAt+380})),state.extraRecords||[]).rows,clock=state.clock||initial.anchor,tab='search',filter={q:'',period:'60',host:'',group:'',service:'',source:'',env:'',business:'',level:''},offset=0,selected=null,form='',editId='',live=false,paused=false,pausedAt=null,buffer=[],timer=null,liveCount=0,showing=false;
  const size=25,tabs=[['search','检索工作台'],['patterns','异常模式'],['audit','登录审计'],['sources','采集源'],['pipeline','解析与脱敏'],['rules','日志告警'],['quality','质量与保留']];
  const labels={healthy:'采集正常',delayed:'延迟',gap:'存在缺口',pending:'待接入',unsupported:'能力待确认',paused:'已停用'};
  const button=(label,action,id='',cls='')=>`<button type="button" data-lg="${action}" data-id="${esc(id)}" class="${cls}">${label}</button>`;
  const tag=(label,type='')=>`<span class="lg-tag ${type}">${esc(label)}</span>`;
  const time=(n,full=false)=>Number.isFinite(n)?new Date(n).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false,...(full?{}:{hour:'2-digit',minute:'2-digit',second:'2-digit'})}):'未知';
  const local=n=>new Date(n+28800000).toISOString().slice(0,16);
  const options=(items,value)=>items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('');
  const field=(label,id,items,value)=>`<label>${label}<select id="lg-${id}">${options(items,value)}</select></label>`;
  const assets=()=>[...db().servers,...db().switches],groupList=()=>window.InfraWorkspaceCore.groups(db().containers);
  const lookup=id=>assets().find(x=>x.id===id);
  function save(message=''){state.clock=clock;state.extraRecords=records.filter(r=>r.id.startsWith('demo-live:'));try{localStorage.setItem(key,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}if(message)feedback.textContent=message+(storageOK?' 已保存到当前浏览器。':' 本地存储不可用，仅本次会话有效。');}
  function sourceName(id){return state.sources.find(s=>s.id===id)?.name||id;}
  function enriched(){const groups=groupList();return records.map(r=>{const h=lookup(r.host),c=db().containers.find(c=>c.id===r.instance),g=groups.find(g=>g.id===r.group),v=db().services.find(v=>v.id===r.service);return {...r,hostName:h?.name||r.host,sourceName:sourceName(r.source),groupName:g?.name||'',instanceName:c?.name||r.instance,serviceName:v?.name||'',env:h?.env||'未分类',business:v?.business||c?.business||h?.business||'未归属',owner:h?.owner||'未分配'};});}
  function range(){const end=paused&&pausedAt?pausedAt:clock;return filter.period==='custom'?{from:C.localTime(filter.from||''),to:C.localTime(filter.to||'')}:{from:end-Number(filter.period)*60000,to:end+1};}
  function result(){const hidden=new Set(buffer);return C.select(enriched().filter(r=>!hidden.has(r.id)),{...filter,...range()});}
  function stat(label,value,sub,tone=''){return `<article class="lg-stat ${tone}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></article>`;}
  function head(){return `<div class="page-heading lg-heading"><div><span class="lg-eyebrow">OBSERVABILITY / LOG EXPLORER</span><h2>日志中心<span class="lg-title-dot"></span></h2><p>从一条日志，追溯一次故障。</p></div><div class="lg-heading-meta">${tag('模拟数据 · 无真实接入','neutral')}<span>演示时间 ${time(clock,true)} · UTC+08:00</span></div></div><div class="lg-tabs" role="tablist" aria-label="日志功能">${tabs.map(([id,name])=>`<button role="tab" aria-selected="${tab===id}" data-lg="tab" data-id="${id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</div>`;}
  function selectFilters(){const unique=k=>[...new Set(enriched().map(r=>r[k]))].sort();return `<section class="lg-panel lg-query"><form id="lg-search-form"><div class="lg-query-line"><span class="lg-search-icon">${window.InfraWorkspace.icon('search')}</span><input aria-label="日志查询条件" id="lg-query" value="${esc(filter.q)}" placeholder='搜索关键字，或 group:office-api level:ERROR'><button class="main" type="submit">检索日志</button>${button('重置','reset')}</div><div class="lg-filters">${field('时间范围','period',[['15','最近 15 分钟'],['60','最近 1 小时'],['1440','最近 24 小时'],['custom','自定义时间']],filter.period)}${field('环境','env',[['','全部环境'],...unique('env')],filter.env)}${field('业务','business',[['','全部业务'],...unique('business')],filter.business)}${field('服务器 / 设备','host',[['','全部设备'],...assets().map(x=>[x.id,x.name])],filter.host)}${field('Docker 名称组','group',[['','全部分组'],...groupList().map(g=>[g.id,`${g.name} · ${g.environment} / ${g.project}`])],filter.group)}${field('服务','service',[['','全部服务'],...db().services.map(v=>[v.id,v.name])],filter.service)}${field('日志源','source',[['','全部日志源'],...state.sources.map(s=>[s.id,s.name])],filter.source)}${field('级别','level',[['','全部级别'],...C.levels],filter.level)}</div>${filter.period==='custom'?`<div class="lg-custom"><label>起始（CST）<input type="datetime-local" id="lg-from" value="${esc(filter.from||local(clock-3600000))}"></label><label>结束（不含此时刻）<input type="datetime-local" id="lg-to" value="${esc(filter.to||local(clock))}"></label><span>依据事件时间；缺失时使用采集时间并标记。</span></div>`:''}<details class="lg-help"><summary>查询语法与时间口径</summary><p>空格表示 AND，双引号匹配短语，前缀 - 排除；字段值做不区分大小写的包含匹配。支持 level、host、source、group、service、trace、actor、event、pattern。示例：<code>level:ERROR -"health check"</code>。当前 Demo 不执行正则、SQL、OR 或通配查询。时间区间为 [开始, 结束)，所有时间按 UTC+08:00 展示。</p></details></form><div class="lg-saved"><span>已存视图</span>${state.views.map(v=>button(esc(v.name),'view',v.id,'lg-chip')).join('')||'<small>常用筛选可以保存</small>'}<input id="lg-view-name" aria-label="视图名称" maxlength="40" placeholder="例如：生产接口错误">${button('保存视图','save-view')}${state.views.length?button('移除全部视图','clear-views'):''}</div></section>`;}
  function histogram(rows){const r=range(),bins=C.histogram(rows,r.from,r.to),max=Math.max(1,...bins.map(b=>b.total));return `<section class="lg-panel lg-histogram"><div class="lg-panel-head"><h3>日志分布 <small>点击柱状条缩小时间范围</small></h3><div class="lg-legend"><i></i>全部日志<i class="error"></i>ERROR / FATAL</div></div><div class="lg-bars" role="group" aria-label="${rows.length} 条日志的时间分布">${bins.map((b,i)=>`<button data-lg="bin" data-id="${i}" aria-label="${time(b.from)} 到 ${time(b.to)}，${b.total} 条，其中错误 ${b.errors} 条" title="${time(b.from)}–${time(b.to)} · ${b.total} 条 / ${b.errors} 错误"><span style="height:${Math.max(2,b.total/max*100)}%"><i style="height:${b.total?b.errors/b.total*100:0}%"></i></span></button>`).join('')}</div><div class="lg-axis"><span>${time(r.from)}</span><span>30 个等宽区间 · 已按筛选条件统计</span><span>${time(r.to)}</span></div></section>`;}
  function rowTable(rows){if(!rows.length)return `<div class="lg-empty">${window.InfraWorkspace.icon('search')}<strong>当前条件下没有日志</strong><p>可调整时间或筛选条件；零条结果不能证明服务正常，也不能证明采集完整。</p>${button('清空筛选','reset')}</div>`;return `<div class="wrap"><table class="lg-log-table"><thead><tr><th>事件时间 <small>CST</small></th><th>级别</th><th>设备 / Docker 组</th><th>日志正文</th><th>上下文</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="lg-mono">${time(C.timestamp(r))}<small>${r.eventAt==null?'采集时间回退':r.observedAt<r.eventAt?'时钟偏差':'+ '+((r.observedAt-r.eventAt)/1000).toFixed(2)+'s 观测差'}</small></td><td>${tag(r.level,r.level.toLowerCase())}</td><td><strong>${esc(r.hostName)}</strong><small>${esc(r.groupName||r.sourceName)}${r.instanceName?' / '+esc(r.instanceName):''}</small></td><td class="lg-message">${button(esc(r.message.split('\n')[0]),'detail',r.id,'lg-message-link')}<small>${esc(r.serviceName||r.business)} · ${esc(r.sourceName)}${r.message.includes('\n')?' · 多行事件':''}</small></td><td>${button('查看 ↗','detail',r.id,'lg-quiet')}</td></tr>`).join('')}</tbody></table></div>`;}
  function search(){const found=result(),rows=found.rows;offset=Math.min(offset,Math.max(0,Math.floor((rows.length-1)/size)*size));const l=C.lag(rows),errors=rows.filter(r=>['ERROR','FATAL'].includes(r.level)).length;return `<div class="lg-stats">${stat('匹配日志',rows.length.toLocaleString(),'当前筛选 · 样本记录')}${stat('错误日志',errors,'ERROR + FATAL','danger')}${stat('观测时间差 P95',l.p95==null?'—':(l.p95/1000).toFixed(2)+'<em>s</em>',`有效 ${l.valid} 条 · 不含时钟异常 ${l.skew} 条`)}${stat('采集需关注',state.sources.filter(s=>s.gap||s.state==='delayed').length,'缺口与延迟独立于业务状态','warning')}</div>${selectFilters()}${found.error?`<div class="lg-error" role="alert">${esc(found.error)}</div>`:histogram(rows)}<section class="lg-panel"><div class="lg-panel-head"><h3>日志事件 <span class="lg-count">${rows.length}</span></h3><div class="lg-actions">${tag(live?'模拟追踪已开启':'历史快照',live?'info':'neutral')}${button(live?'停止追踪':'启动模拟追踪','live')}${live||paused?button(paused?`继续显示（${buffer.length} 条缓冲）`:'暂停显示','pause'):''}${button('脱敏导出 CSV','export')}</div></div>${rowTable(rows.slice(offset,offset+size))}<div class="lg-table-footer"><span>${rows.length?offset+1:0}–${Math.min(offset+size,rows.length)} / ${rows.length} 条 · 每页 ${size} 条</span><div>${button('上一页','prev','',offset===0?'lg-disabled':'')}${button('下一页','next','',offset+size>=rows.length?'lg-disabled':'')}</div></div><div class="lg-footnote">所有行来自固定演示数据。模拟追踪每 5 秒生成 1 条测试日志；记录保存在当前浏览器。最多缓存 100 条暂停消息，满后自动停止模拟生产。</div></section>`;}
  function patterns(){const found=result(),groups=C.patterns(found.rows),errors=groups.filter(g=>['ERROR','FATAL'].includes(g.sample.level));return `<div class="lg-intro"><div><h3>把重复错误收拢成可处理的问题</h3><p>保留日志源、Docker 名称组与错误类型边界；数字和请求标识归一化。聚类是确定性模板规则，不代表 AI 已确认根因。</p></div>${button('调整检索范围','tab','search')}</div><div class="lg-stats">${stat('当前范围日志',found.rows.length,'沿用检索工作台的全部筛选')}${stat('日志模式',groups.length,'按来源、归属与级别隔离')}${stat('错误模式',errors.length,'ERROR / FATAL')}${stat('基线对比','待积累','需要可比的历史窗口')}</div>${found.error?`<div class="lg-error">${esc(found.error)}</div>`:''}<section class="lg-panel"><div class="lg-panel-head"><h3>模式排行榜</h3><small>按出现次数降序</small></div><div class="wrap"><table><thead><tr><th>级别 / 模式</th><th>次数</th><th>设备</th><th>首次 / 最近</th><th>操作</th></tr></thead><tbody>${groups.map((g,i)=>`<tr><td>${tag(g.sample.level,g.sample.level.toLowerCase())}<code class="lg-pattern">${esc(g.template.split('\n')[0])}</code><small>${esc(g.sample.groupName||g.sample.sourceName)}</small></td><td><strong class="lg-big-number">${g.rows.length}</strong></td><td>${g.hosts.size}</td><td>${time(g.first)}<small>${time(g.last)}</small></td><td>${button('查看事件','pattern',String(i))}</td></tr>`).join('')||'<tr><td colspan="5">当前范围没有模式；请调整检索条件。</td></tr>'}</tbody></table></div></section>`;}
  function audit(){const found=result(),rows=found.rows.filter(r=>r.outcome),count=k=>rows.filter(r=>r.outcome===k).length;return `<div class="lg-intro"><div><h3>登录审计与账号行为</h3><p>登录账号与设备使用人分别记录。失败原因、来源 IP、登录类型和事件编号一起保留，避免把网络登录误认为人工登录。</p></div>${button('调整筛选 / 时间','tab','search')}</div><div class="lg-stats">${stat('登录成功',count('success'),'Windows 4624 / SSH')}${stat('登录失败',count('failure'),'Windows 4625 / SSH','danger')}${stat('提权 / 特权',count('privilege'),'sudo / Windows 4672','warning')}${stat('审计清除',count('audit_clear'),'Windows 1102 · 单独保留','warning')}</div>${found.error?`<div class="lg-error">${esc(found.error)}</div>`:''}<section class="lg-panel"><div class="lg-panel-head"><h3>账号活动时间线</h3><small>继承检索工作台的当前筛选</small></div><div class="wrap"><table><thead><tr><th>时间 / 事件</th><th>账号</th><th>结果 / 登录方式</th><th>来源 IP</th><th>设备 / 运维组</th><th>证据</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${time(C.timestamp(r))}<small>${esc(r.eventCode)}</small></td><td><strong>${esc(r.actor)}</strong></td><td>${tag({success:'成功',failure:'失败',privilege:'特权操作',audit_clear:'审计清除'}[r.outcome],r.outcome==='success'?'info':'warn')}<small>${esc(r.loginType)}</small></td><td class="lg-mono">${esc(r.sourceIP||'未提供')}</td><td>${esc(r.hostName)}<small>${esc(r.owner)}</small></td><td>${button('原始事件','detail',r.id)}</td></tr>`).join('')||'<tr><td colspan="6">当前条件没有登录审计记录。请检查时间、日志源和审计权限。</td></tr>'}</tbody></table></div></section><div class="lg-note">只有启用了相应系统审计、且采集账号有读取权限时才会有这些事件。账号行为只作运维审计；生产版需按职责限制访问并记录查询与导出。</div>`;}
  function sources(){return `<div class="lg-intro"><div><h3>每个来源，都有明确的采集边界</h3><p>服务器、容器和设备采用不同接入方式。新增配置保持“待接入”，不会自动生成历史数据。</p></div>${button('+ 添加日志源','source-new','','main')}</div><section class="lg-panel"><div class="lg-panel-head"><h3>日志源清单 <span class="lg-count">${state.sources.length}</span></h3><small>Agent / 网关采集配置草稿</small></div><div class="wrap"><table><thead><tr><th>日志源 / 对象</th><th>接入方式 / 范围</th><th>续传位置</th><th>采集状态</th><th>待传 / 重试</th><th>操作</th></tr></thead><tbody>${state.sources.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(lookup(s.host)?.name||s.host)}${s.group?' · '+esc(groupList().find(g=>g.id===s.group)?.name||'原分组已移除'):''}</small></td><td>${esc(s.type)}<small class="lg-locator">${esc(s.locator)}</small></td><td><small>${esc(s.checkpoint)}</small></td><td>${tag(s.enabled===false?'已停用':labels[s.state]||s.state,s.gap?'error':s.state==='healthy'?'info':'warn')}<small>${s.heartbeat?'心跳 '+time(s.heartbeat):'未收到采集心跳'}</small></td><td>${Number(s.backlog||0)} 条<small>${Number(s.retries||0)} 次重试</small></td><td>${button('查看日志','source-search',s.id)}${button('编辑','source-edit',s.id)}${button(s.enabled===false?'启用':'停用','source-toggle',s.id)}</td></tr>`).join('')}</tbody></table></div></section><div class="lg-two-col"><section class="lg-panel lg-padded"><h3>网管设备接入</h3><p>交换机优先使用设备支持的 Syslog TCP/TLS；仅支持 UDP 时，显示“不可确认传输完整性”。NAS、打印机和扫描仪按厂商能力接入，SNMP 指标不能替代审计日志。</p></section><section class="lg-panel lg-padded"><h3>Docker 采集检查</h3><p>先检查日志驱动和回读能力。组级查询、实例级游标；容器重建会产生新实例，保留旧实例日志。配置不读取 Docker 日志存储内部文件。</p></section></div>`;}
  function pipeline(){const sample=JSON.stringify({timestamp:'2026-10-18T02:09:10+08:00',level:'error',message:'upstream request timeout',service:'office-api',authorization:'Bearer DEMO_ONLY',context:{password:'DEMO_ONLY',trace_id:'4bf92f3577b34da6a3ce929d0e0e4736'}},null,2);return `<div class="lg-intro"><div><h3>先规范，再索引</h3><p>演示解析器支持 JSON 与纯文本；这里只预览一条已合并事件。文件轮转、多行拼接和故障重试属于待实现的 Rust Agent 能力。</p></div>${tag('预览输入不保存','neutral')}</div><div class="lg-pipeline-stages"><span><b>01</b>来源与游标</span><span><b>02</b>多行合并</span><span><b>03</b>结构解析</span><span><b>04</b>时间规范</span><span><b>05</b>敏感字段脱敏</span><span><b>06</b>索引 / 隔离</span></div><div class="lg-two-col"><section class="lg-panel lg-padded"><div class="lg-panel-head"><h3>输入样本</h3>${field('格式','parser',[['json','JSON 对象'],['text','纯文本 / 已合并多行']],'json')}</div><label class="lg-sr-only" for="lg-sample">解析样本</label><textarea id="lg-sample" spellcheck="false">${esc(sample)}</textarea><div class="lg-actions">${button('运行解析与脱敏','parse','','main')}${button('载入多行示例','sample-multiline')}</div><small>最多 256 KiB；请使用测试文本。原始输入不会写入本地存储。</small></section><section class="lg-panel lg-padded"><h3>规范化结果</h3><pre id="lg-parsed" class="lg-code">点击“运行解析与脱敏”查看结果。</pre></section></div><section class="lg-panel lg-padded"><h3>生产采集处理约定</h3><div class="lg-policy-grid"><div><strong>多行有边界</strong><p>按源设置起始规则；候选上限 256 KiB / 500 行 / 2 秒。达到限制标记截断或隔离，不静默吞掉。</p></div><div><strong>时间不猜测</strong><p>事件时间、Agent 观测时间、服务端入库时间分别保留；无时区或解析失败时显示质量标志。</p></div><div><strong>失败可回查</strong><p>解析失败仍进入脱敏隔离区，记录解析器版本、原因和数量；修正后可重放。</p></div><div><strong>先脱敏后发送</strong><p>已覆盖常见密码、Token、Authorization 和 Cookie 的示例规则；生产需按业务字段补齐并回归验证。</p></div></div></section>`;}
  function rules(){return `<div class="lg-intro"><div><h3>日志告警进入同一个响应入口</h3><p>在完整窗口内按事件时间计数。采集缺口、源不可用或窗口未完成时返回“未知”，保留已有事件，不制造“恢复”。</p></div><div class="lg-actions">${button('+ 新建规则','rule-new','','main')}<button data-page="alerts">统一告警看板 ↗</button></div></div><section class="lg-panel"><div class="lg-panel-head"><h3>规则与最近评估</h3><small>演示采用 2 秒事件时间水位；源延迟会阻止评估</small></div><div class="wrap"><table><thead><tr><th>规则 / 查询</th><th>作用域</th><th>窗口 / 阈值</th><th>通知对象</th><th>评估状态</th><th>操作</th></tr></thead><tbody>${state.rules.map(r=>{const run=state.runtime[r.id];return `<tr><td><strong>${esc(r.name)}</strong><small><code>${esc(r.q)}</code></small></td><td>${esc(sourceName(r.source))}</td><td>${r.window} 分钟 ≥ ${r.threshold} 条<small>${esc(r.severity)}</small></td><td>${esc(r.receiver)}<small>${esc(r.channel)} · 模拟</small></td><td>${tag(!r.enabled?'已禁用':run?{firing:'触发',normal:'正常',unknown:'未知'}[run.state]:'未评估',run?.state==='firing'?'error':run?.state==='unknown'?'warn':'neutral')}<small>${run?time(run.evaluatedAt)+(run.count==null?'':' · '+run.count+' 条'):''}</small>${run?.reason?`<small class="lg-rule-reason">${esc(run.reason)}</small>`:''}</td><td>${button('评估','rule-run',r.id)}${button('编辑','rule-edit',r.id)}${button(r.enabled?'禁用':'启用','rule-toggle',r.id)}</td></tr>`;}).join('')}</tbody></table></div></section><div class="lg-two-col"><section class="lg-panel lg-padded"><h3>事件状态演练</h3><p>“载入恢复窗口”会追加有效的成功样本并推进 6 分钟演示时间；采集缺口继续保留。只有新的、完整的正常窗口才能恢复事件。</p>${button('载入恢复窗口','recovery')}</section><section class="lg-panel lg-padded"><h3>通知与防重复</h3><p>同一规则未恢复前复用同一事件。企业微信 / 邮件只写入模拟投递记录；生产还需持久通知队列、去重键、退避重试、值班升级及送达回执。</p><button data-page="notify">查看通知渠道 ↗</button></section></div>`;}
  function quality(){const lag=C.lag(enriched()),queue=state.sources.reduce((n,s)=>n+(s.backlog||0),0);return `<div class="lg-intro"><div><h3>日志可信度，必须可见</h3><p>源端产生量无法确认时，完整率显示未知。接入计数、隔离计数、续传位置与心跳分别衡量。</p></div>${button('评估采集健康','source-health','','main')}</div><div class="lg-stats">${stat('端到端完整率','未知','缺少所有源端产生计数')}${stat('待传队列',queue+'<em>条</em>','队列积压不能当作丢失数量','warning')}${stat('时间质量异常',lag.skew+lag.missing,`${lag.skew} 条时钟异常 / ${lag.missing} 条无事件时间`)}${stat('当前演示事件',records.length,'按事件 ID 去重后的记录')}</div><section class="lg-panel"><div class="lg-panel-head"><h3>采集链路检查</h3><small>以下为演示快照，不是在线服务指标</small></div><div class="wrap"><table><thead><tr><th>来源</th><th>批次 ACK</th><th>解析隔离 / 拒收</th><th>事件时间水位</th><th>完整性证据</th></tr></thead><tbody>${state.sources.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.heartbeat?s.ackMs+' ms':'未知'}</td><td>${s.parseErrors||0} / ${s.rejected||0}<small>隔离计数来自独立示例计数器</small></td><td>${time(s.watermark)}<small>${s.watermark?'窗口只评估到水位之前':'尚未建立'}</small></td><td class="lg-evidence">${esc(s.gapNote||(s.state==='unsupported'?'设备能力尚未确认':s.state==='pending'?'尚未接入':s.type==='Syslog TLS'?'仅确认接入侧；设备产生总量未知':'已记录续传位置，不能据此承诺绝对零丢失'))}</td></tr>`).join('')}</tbody></table></div></section><div class="lg-two-col"><section class="lg-panel lg-padded"><h3>分级保留策略</h3><form id="lg-retention-form" class="lg-retention"><label>在线检索（天）<input id="lg-hot" type="number" min="1" max="365" value="${state.retention.hot}" required></label><label>归档总保留（天）<input id="lg-archive" type="number" min="1" max="3650" value="${state.retention.archive}" required></label><label>登录审计总保留（天）<input id="lg-audit" type="number" min="1" max="3650" value="${state.retention.audit}" required></label><button type="submit" class="main">保存策略草稿</button></form><small>示例默认值不是合规期限；此操作不会删除 Demo 数据。生产需按公司制度设置归档、法律保全和销毁任务。</small></section><section class="lg-panel lg-padded"><h3>操作留痕</h3><div class="lg-action-log">${state.actions.slice(-8).reverse().map(x=>`<div><time>${time(x.at,true)}</time><span>${esc(x.text)}</span></div>`).join('')||'<p>尚无操作记录。保存规则、修改源和导出会留下本地演示记录。</p>'}</div><small>浏览器记录可被修改；生产审计必须由后端记录并做访问隔离。</small></section></div><div class="lg-note"><strong>存储分工：</strong>PostgreSQL 保存资产、规则、人员、审计元数据和事件索引；小规模日志可先按时间分区。大量日志正文采用独立日志检索存储与对象归档，通过 Rust 查询接口统一检索，避免拖慢监控和告警事务。</div>`;}
  function detail(){const r=enriched().find(r=>r.id===selected);if(!r)return '';const ctx=C.context(enriched(),r),trace=r.traceId?enriched().filter(x=>x.traceId===r.traceId):[],fields={...r.fields,resource:{host:r.hostName,service:r.serviceName,docker_group:r.groupName,container:r.instanceName},event_id:r.id,source_generation:r.generation,stream:r.stream,sequence:r.sequence};return `<div class="lg-backdrop" data-lg="close"></div><aside class="lg-inspector" role="dialog" aria-modal="true" aria-labelledby="lg-detail-title" tabindex="-1"><div class="lg-panel-head"><div><span class="lg-eyebrow">EVENT INSPECTOR</span><h3 id="lg-detail-title">日志事件详情</h3></div>${button('关闭 ×','close')}</div><div class="lg-detail-title">${tag(r.level,r.level.toLowerCase())}<strong>${esc(r.hostName)}</strong></div><pre class="lg-code">${esc(r.message)}</pre><dl class="lg-facts"><dt>事件时间</dt><dd>${time(r.eventAt,true)}${r.eventAt==null?' · 查询时回退到采集时间':''}</dd><dt>采集观测时间</dt><dd>${time(r.observedAt,true)}</dd><dt>服务端入库时间</dt><dd>${time(r.ingestedAt,true)}</dd><dt>业务 / 服务</dt><dd>${esc(r.business)} / ${esc(r.serviceName||'未关联')}</dd><dt>Docker 组 / 实例</dt><dd>${esc(r.groupName||'不适用')} / ${esc(r.instanceName||'不适用')}</dd><dt>Trace ID</dt><dd class="lg-mono">${esc(r.traceId||'未提供；不能自动补出链路')}</dd><dt>来源 / 游标</dt><dd>${esc(r.sourceName)} / ${r.sequence}</dd></dl><details class="lg-help"><summary>输入记录（脱敏样本）</summary><pre class="lg-code">${esc(JSON.stringify(C.redact({timestamp:r.eventAt==null?null:new Date(r.eventAt).toISOString(),level:r.level,body:r.message,event_code:r.eventCode||null,actor:r.actor||null,source_ip:r.sourceIP||null,...r.fields}),null,2))}</pre></details><h4>结构化字段</h4><pre class="lg-code">${esc(JSON.stringify(C.redact(fields),null,2))}</pre><h4>同一来源、实例与代次的前后文</h4><small>不沿用级别和关键字筛选，避免漏掉故障前的正常事件。</small><div class="lg-context">${ctx.map(x=>`<button data-lg="detail" data-id="${esc(x.id)}" class="${x.id===r.id?'selected':''}"><time>${time(C.timestamp(x))}</time>${tag(x.level,x.level.toLowerCase())}<span>${esc(x.message.split('\n')[0])}</span></button>`).join('')}</div>${r.traceId?`<h4>相同 Trace ID 的日志 · ${trace.length} 条</h4><div class="lg-context">${trace.map(x=>button(esc(x.hostName+' / '+x.sourceName+' · '+x.message.split('\n')[0]),'detail',x.id)).join('')}</div><small>这是日志关联；未接入 Span 数据，不能展示完整调用链。</small>`:''}<div class="lg-actions">${button('按此来源检索','source-search',r.source)}${r.traceId?button('按 Trace 检索','trace',r.traceId):''}<button data-page="traffic">打开历史流量 ↗</button></div><p class="lg-note">流量页独立选择同一设备与时间段。日志只能提供关联证据，单条超时日志不足以确认网络或数据库根因。</p></aside>`;}
  function formPanel(){if(!form)return '';const source=form==='source',obj=source?state.sources.find(s=>s.id===editId):state.rules.find(s=>s.id===editId);return `<div class="lg-backdrop" data-lg="close"></div><aside class="lg-inspector" role="dialog" aria-modal="true" aria-labelledby="lg-form-title" tabindex="-1"><div class="lg-panel-head"><h3 id="lg-form-title">${obj?'编辑':'新增'}${source?'日志源':'日志告警规则'}</h3>${button('关闭 ×','close')}</div><form id="lg-editor" class="lg-editor"><label>名称<input name="name" maxlength="80" required value="${esc(obj?.name||'')}"></label>${source?`<label>设备<select name="host">${options(assets().map(x=>[x.id,x.name]),obj?.host||assets()[0]?.id)}</select></label><label>采集方式<select name="type">${options(['journald','Windows Event Log','文件','Docker API','Syslog TLS','Syslog UDP','NAS API','PVE API','OTLP','能力待确认'],obj?.type||'journald')}</select></label><label>Docker 名称组（Docker API 必选）<select name="group">${options([['','不适用'],...groupList().map(g=>[g.id,`${g.name} · ${g.environment} / ${g.project}`])],obj?.group||'')}</select></label><label>通道 / 路径 / 只读接入位置<input name="locator" maxlength="300" required value="${esc(obj?.locator||'')}"></label><label>解析格式<select name="parser">${options([['text','纯文本'],['json','JSON'],['native','协议原生字段']],obj?.parser||'text')}</select></label><p class="lg-note">凭据通过生产凭据库引用；此 Demo 不填写密码。保存新的源配置后为“待接入”；变更采集身份时重建游标，不沿用旧日志。</p>`:`<label>日志源<select name="source">${options(state.sources.filter(s=>s.enabled!==false&&s.state!=='unsupported').map(s=>[s.id,s.name]),obj?.source||'ls-office')}</select></label><label>匹配条件<input name="q" value="${esc(obj?.q||'level:ERROR')}" required maxlength="300"></label><div class="lg-two-col"><label>窗口（分钟）<input name="window" type="number" min="1" max="60" value="${obj?.window||5}" required></label><label>触发条数 ≥<input name="threshold" type="number" min="1" max="100000" value="${obj?.threshold||5}" required></label></div><label>级别<select name="severity">${options(['严重','警告','提示'],obj?.severity||'警告')}</select></label><label>通知渠道<select name="channel">${options(['企业微信 + 邮件','企业微信','邮件'],obj?.channel||'企业微信 + 邮件')}</select></label><label>接收人 / 值班组<input name="receiver" list="lg-people" maxlength="120" required value="${esc(obj?.receiver||'业务值班组')}"><datalist id="lg-people">${(window.InfraWorkspace.listPeople?.()||[]).map(p=>`<option value="${esc(p.name+' · '+(p.department||p.id))}"></option>`).join('')}</datalist></label><p class="lg-note">这里保存通知路由草稿。生产须解析为企业微信成员 ID / 值班组 ID，不能仅凭同名人员自动投递。</p>`}<div id="lg-form-error" class="lg-error" hidden></div><div class="lg-actions"><button type="submit" class="main">保存${source?'配置':'规则'}</button>${button('取消','close')}</div></form></aside>`;}
  function render(){showing=true;root.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='logs'));try{history.replaceState(null,'','#logs');}catch{}content.innerHTML=`<div id="lg-app">${head()}${({search,patterns,audit,sources,pipeline,rules,quality}[tab])()}${selected?detail():''}${form?formPanel():''}</div>`;if(selected||form)content.querySelector('.lg-inspector')?.focus();}
  function record(text){state.actions.push({at:Date.now(),text});state.actions=state.actions.slice(-100);}
  function readFilters(){filter.q=content.querySelector('#lg-query')?.value||'';for(const k of ['period','env','business','host','group','service','source','level']){const el=content.querySelector('#lg-'+k);if(el)filter[k]=el.value;}if(filter.period==='custom'){filter.from=content.querySelector('#lg-from')?.value||filter.from||local(clock-3600000);filter.to=content.querySelector('#lg-to')?.value||filter.to||local(clock);}offset=0;}
  function stop(){live=false;paused=false;buffer=[];if(timer)clearInterval(timer);timer=null;}
  function sample(recovery=false){const src=state.sources.find(s=>s.id==='ls-office');if(!src||src.enabled===false||src.state!=='healthy'){stop();feedback.textContent='示例 office-api 源不可用，模拟追踪已停止。';return;}clock+=recovery?360000:5000;for(const s of state.sources)if(s.heartbeat&&s.enabled!==false&&s.state!=='pending'){s.heartbeat=clock;s.watermark=clock-(s.state==='delayed'?47000:2000);}const c=db().containers.find(c=>c.id==='c1');if(!c){stop();return;}const id='demo-live:'+clock,seq=10000+(++liveCount),r={id,source:'ls-office',host:c.host,group:c.monitorGroupId||'',instance:c.id,stream:c.id+'/stdout',generation:'demo-epoch-1',sequence:seq,eventAt:clock-2500,observedAt:clock-1000,ingestedAt:clock-620,level:'INFO',message:recovery?'request completed status=200 recovery_window=true':'request completed status=200 simulated_tail='+liveCount,service:'v2',traceId:'',actor:'',outcome:'',patternKey:'request_ok',fields:{http_status:200,simulated:true}};records=C.dedupe(records,[r]).rows;if(paused)buffer.push(id);if(buffer.length>=100||records.length>=2000){live=false;if(timer)clearInterval(timer);timer=null;feedback.textContent='达到模拟消息上限，已停止生产；可继续显示缓冲记录。';}save();if(showing&&tab==='search'&&!selected&&!form&&!document.activeElement?.matches?.('input,textarea,select'))render();}
  function evaluate(id){const r=state.rules.find(r=>r.id===id);if(!r||!r.enabled){feedback.textContent='规则已禁用。';return;}const end=clock-2000,res=C.rule(r,enriched(),state.sources,end);state.runtime[id]={...res,evaluatedAt:clock};const events=window.InfraOps.events(),existing=events.find(e=>e.kind==='logs'&&e.rule==='log:'+id&&!e.resolved);if(res.state==='firing'){if(existing){existing.updated=clock;existing.value=res.count+' 条 / '+r.window+' 分钟';existing.logEvidence={from:res.from,to:res.to,ids:res.ids,query:r.q,source:r.source};}else events.unshift({id:'evt-log-'+id+'-'+clock,rule:'log:'+id,kind:'logs',target:r.source,targetName:sourceName(r.source),business:lookup(state.sources.find(s=>s.id===r.source)?.host)?.business||'未归属',severity:r.severity,title:r.name,value:res.count+' 条 / '+r.window+' 分钟',at:clock,updated:clock,resolved:null,ack:false,silencedUntil:null,channel:r.channel,receiver:r.receiver,delivery:'模拟通知任务 · 未发送',logEvidence:{from:res.from,to:res.to,ids:res.ids,query:r.q,source:r.source},timeline:[{at:clock,text:'完整日志窗口达到阈值，生成事件与模拟通知任务'}]});}else if(existing&&res.state==='normal'&&clock>existing.updated){existing.resolved=clock;existing.updated=clock;existing.timeline.push({at:clock,text:'新的完整窗口低于阈值，日志事件恢复（模拟）'});}else if(existing&&res.state==='unknown'){existing.updated=clock;if(!existing.timeline.some(t=>t.at===clock&&t.text.startsWith('日志采集')))existing.timeline.push({at:clock,text:'日志采集状态未知，保留故障状态，不推断恢复'});}window.InfraOps.persist();record('评估规则：'+r.name+' → '+res.state);save('已评估：'+{firing:'已进入统一告警看板',normal:'正常窗口',unknown:'数据不完整，状态未知'}[res.state]+'；没有发送真实通知。');render();}
  function evaluateHealth(){const events=window.InfraOps.events();let firing=0;for(const source of state.sources){const h=C.health(source,clock),rule='log-source:'+source.id,existing=events.find(e=>e.rule===rule&&!e.resolved);if(h.state==='firing'){firing++;if(existing){existing.updated=clock;existing.value=h.reason;}else events.unshift({id:'evt-'+rule+'-'+clock,rule,kind:'logs',target:source.id,targetName:source.name,business:lookup(source.host)?.business||'未归属',severity:'警告',title:'日志采集异常',value:h.reason,at:clock,updated:clock,resolved:null,ack:false,silencedUntil:null,channel:'企业微信 + 邮件',receiver:'平台运维组',delivery:'模拟通知任务 · 未发送',logEvidence:{from:clock-1800000,to:clock,ids:[],query:'',source:source.id},timeline:[{at:clock,text:'采集健康规则触发：'+h.reason+'；这不代表业务本身故障'}]});}else if(existing&&h.state==='normal'&&clock>existing.updated){existing.resolved=clock;existing.updated=clock;existing.timeline.push({at:clock,text:'新的采集观测满足健康阈值，历史缺口仍需单独审计'});}}window.InfraOps.persist();record('评估采集健康：'+firing+' 个异常来源');save('已识别 '+firing+' 个采集异常并汇入统一告警看板；未接入和停用源不参与评估。');render();}
  function editorSubmit(el){const d=new FormData(el),value=k=>String(d.get(k)||'').trim(),source=form==='source',name=value('name');let error='';if(!name)error='请输入名称。';if(source){const type=value('type'),host=lookup(value('host')),group=groupList().find(g=>g.id===value('group'));if(!host)error='所选设备不存在。';else if(type==='Windows Event Log'&&host.os!=='Windows')error='Windows Event Log 需选择 Windows 设备。';else if(type==='journald'&&host.os!=='Linux')error='journald 需选择 Linux 设备。';else if(type==='Docker API'&&(!group||!group.hosts.includes(host.id)))error='请选择属于该设备的 Docker 名称组。';else if(!value('locator'))error='请输入通道、文件路径或接入位置。';if(!error){const old=state.sources.find(s=>s.id===editId),changed=!old||['type','host','group','locator'].some(k=>(old[k]||'')!==value(k)),identityChanged=old&&['type','host','group','locator'].some(k=>(old[k]||'')!==value(k));if(identityChanged){old.enabled=false;old.state='paused';old.name+='（旧配置）';}const item={...(changed?{id:'ls-custom-'+Date.now(),state:'pending',heartbeat:null,watermark:null,captureStart:clock,gap:false,backlog:0,retries:0,rejected:0,parseErrors:0,checkpoint:'等待 Agent 建立续传位置'}:old),name,host:value('host'),type,group:value('group'),locator:value('locator'),parser:value('parser'),enabled:true};if(!old||identityChanged)state.sources.push(item);else Object.assign(old,item);record('保存日志源：'+name);}}
    else{const q=value('q'),w=Number(value('window')),t=Number(value('threshold'));if(C.query(q).error)error=C.query(q).error;else if(!q||!Number.isInteger(w)||w<1||w>60||!Number.isInteger(t)||t<1||t>100000)error='窗口需为 1–60 分钟，阈值需为 1–100000 的整数，并填写匹配条件。';else if(!state.sources.some(s=>s.id===value('source')))error='请选择有效日志源。';else if(!value('receiver'))error='请填写接收人或值班组。';const previousRule=state.rules.find(r=>r.id===editId);if(previousRule&&window.InfraOps.events().some(e=>e.rule==='log:'+editId&&!e.resolved)&&(['q','source'].some(k=>previousRule[k]!==value(k))||previousRule.window!==w||previousRule.threshold!==t))error='该规则有未恢复事件；请新建规则，避免改变历史事件的判定口径。';if(!error){const old=state.rules.find(r=>r.id===editId),item={id:old?.id||'lr-'+Date.now(),name,q,window:w,threshold:t,source:value('source'),severity:value('severity'),receiver:value('receiver'),channel:value('channel'),enabled:old?.enabled??true};if(old)Object.assign(old,item);else state.rules.push(item);delete state.runtime[item.id];record('保存日志规则：'+name);}}
    if(error){const box=content.querySelector('#lg-form-error');box.hidden=false;box.textContent=error;return;}form='';editId='';save('配置草稿已保存；未下发到真实设备。');render();}
  function exportRows(){const found=result();if(found.error){feedback.textContent=found.error;return;}const text=C.csv(found.rows),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='InfraScope_SIMULATED_redacted_logs.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);record('导出脱敏日志：'+Math.min(found.rows.length,2000)+' 条，查询 '+(filter.q||'全部'));save('已导出当前筛选下的脱敏记录（最多 2000 条，非仅当前页）。');}
  root.addEventListener('submit',e=>{if(e.target.id==='lg-search-form'){e.preventDefault();readFilters();render();}else if(e.target.id==='lg-editor'){e.preventDefault();editorSubmit(e.target);}else if(e.target.id==='lg-retention-form'){e.preventDefault();const hot=Number(content.querySelector('#lg-hot').value),archive=Number(content.querySelector('#lg-archive').value),audit=Number(content.querySelector('#lg-audit').value);if(![hot,archive,audit].every(Number.isInteger)||hot<1||hot>365||archive<hot||archive>3650||audit<hot||audit>3650){feedback.textContent='保留天数需为整数，归档与审计总保留不得小于在线检索天数。';return;}state.retention={hot,archive,audit};record('更新保留策略草稿：在线 '+hot+' / 归档 '+archive+' / 审计 '+audit+' 天');save('已保存策略草稿；没有执行数据删除。');}});
  root.addEventListener('change',e=>{if(/^lg-(period|env|business|host|group|service|source|level|from|to)$/.test(e.target.id)){readFilters();render();}});
  root.addEventListener('click',e=>{const b=e.target.closest('[data-lg]');if(!b)return;const a=b.dataset.lg,id=b.dataset.id;
    if(a==='tab'){tab=id;selected=null;form='';render();}
    else if(a==='reset'){filter={q:'',period:'60',host:'',group:'',service:'',source:'',env:'',business:'',level:''};offset=0;render();}
    else if(a==='prev'){offset=Math.max(0,offset-size);render();}else if(a==='next'){if(offset+size<result().rows.length)offset+=size;render();}
    else if(a==='detail'){selected=id;form='';render();}
    else if(a==='close'){selected=null;form='';render();}
    else if(a==='source-search'){stop();filter={q:'',period:'60',source:id};offset=0;selected=null;tab='search';render();}
    else if(a==='trace'){filter={q:'trace:'+id,period:'60'};offset=0;selected=null;tab='search';render();}
    else if(a==='pattern'){const g=C.patterns(result().rows)[Number(id)];if(!g)return;filter.q='pattern:'+g.sample.patternKey;filter.source=g.sample.source;filter.group=g.sample.group||'';filter.level=g.sample.level;offset=0;tab='search';render();}
    else if(a==='bin'){const r=range(),bin=C.histogram(result().rows,r.from,r.to)[Number(id)];if(!bin||!Number.isFinite(bin.from))return;filter.period='custom';filter.from=local(Math.floor(bin.from/60000)*60000);filter.to=local(Math.ceil(bin.to/60000)*60000);offset=0;render();}
    else if(a==='save-view'){readFilters();const name=content.querySelector('#lg-view-name')?.value.trim();if(!name){feedback.textContent='请先填写视图名称。';return;}if(state.views.length>=12){feedback.textContent='演示最多保存 12 个视图。';return;}state.views.push({id:'lv-'+Date.now(),name,filter:structuredClone(filter)});save('已保存筛选视图。');render();}
    else if(a==='view'){const v=state.views.find(v=>v.id===id);if(v){filter=structuredClone(v.filter);offset=0;render();}}
    else if(a==='clear-views'){state.views=[];save('已移除本地保存的筛选视图。');render();}
    else if(a==='live'){if(live){stop();render();}else{live=true;paused=false;buffer=[];filter.period='60';timer=setInterval(()=>sample(),5000);render();}}
    else if(a==='pause'){paused=!paused;pausedAt=paused?clock:null;if(!paused)buffer=[];render();}
    else if(a==='export')exportRows();
    else if(a==='source-new'||a==='source-edit'){form='source';editId=a==='source-edit'?id:'';selected=null;render();}
    else if(a==='source-toggle'){const s=state.sources.find(s=>s.id===id);if(s){s.enabled=s.enabled===false;record((s.enabled?'启用':'停用')+'日志源：'+s.name);save('采集开关草稿已保存。');render();}}
    else if(a==='rule-new'||a==='rule-edit'){form='rule';editId=a==='rule-edit'?id:'';selected=null;render();}
    else if(a==='rule-toggle'){const r=state.rules.find(r=>r.id===id);if(r){r.enabled=!r.enabled;record((r.enabled?'启用':'禁用')+'日志规则：'+r.name);save('规则开关已更新；已有告警不会被自动恢复。');render();}}
    else if(a==='rule-run')evaluate(id);
    else if(a==='source-health')evaluateHealth();
    else if(a==='parse'){const out=C.parse(content.querySelector('#lg-sample').value,content.querySelector('#lg-parser').value);content.querySelector('#lg-parsed').textContent=out.error||JSON.stringify(out.value,null,2);}
    else if(a==='sample-multiline'){content.querySelector('#lg-parser').value='text';content.querySelector('#lg-sample').value='worker memory allocation failed\n  at billing::worker::run (worker.rs:128)\n  caused by: allocation limit exceeded';}
    else if(a==='recovery'){stop();sample(true);record('载入新的成功样本与完整恢复窗口');save('演示时间推进 6 分钟；请重新评估规则。原有采集缺口仍然保留。');render();}
  });
  root.addEventListener('keydown',e=>{if(!selected&&!form)return;if(e.key==='Escape'){selected=null;form='';render();}else if(e.key==='Tab'){const panel=content.querySelector('.lg-inspector'),items=panel?[...panel.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled):[];if(!items.length)return;if(e.shiftKey&&(document.activeElement===items[0]||document.activeElement===panel)){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
  function openEvidence(e){stop();tab='search';selected=null;form='';filter={q:e.query||'',source:e.source||'',period:'custom',from:local(Math.floor(e.from/60000)*60000),to:local(Math.ceil(e.to/60000)*60000)};offset=0;render();feedback.textContent='已载入告警查询与时间范围（按分钟向外取整）；原始精确窗口和命中 ID 保存在告警证据中。';}
  window.InfraLogs={render,leave:()=>{showing=false;stop();selected=null;form='';},openEvidence,pages:['logs'],testing:{state:()=>state,result,records:()=>records,clock:()=>clock,sample,evaluate}};
})();
